#!/usr/bin/env bash
# Signage Linux player setup, generated by the Signage server "__SERVER_NAME__".
#
# Turns this Raspberry Pi (Raspberry Pi OS Bookworm or newer) or Debian PC into
# a dedicated signage screen:
#   - installs Node.js, Chromium and the cage kiosk window manager
#   - installs the Signage agent: finds the server, pairs with it, keeps an
#     encrypted copy of all scheduled content on disk, updates itself
#   - shows the player fullscreen on the connected screen from boot
#
# Usage:   sudo bash signage-linux-setup.sh
# Remove:  sudo signage-uninstall
set -euo pipefail

ROOT="${SIGNAGE_ROOT:-}"                 # testing: install below another directory
SKIP_SYSTEM="${SIGNAGE_SKIP_SYSTEM:-}"   # testing: no packages, users or services
BASE="$ROOT/opt/signage"
APP="$BASE/app"
ETC="$ROOT/etc/signage-agent"
STATE="$ROOT/var/lib/signage-agent"
RUN_USER=signage
PORT=8099

if [ -z "$SKIP_SYSTEM" ] && [ "$(id -u)" -ne 0 ]; then exec sudo bash "$0" "$@"; fi
say() { printf '\n\033[1m%s\033[0m\n' "$*"; }

if [ -z "$SKIP_SYSTEM" ]; then
  say "Installing packages (Node.js, Chromium, cage)…"
  export DEBIAN_FRONTEND=noninteractive
  apt-get update
  BROWSER_PKG=chromium
  apt-cache show chromium >/dev/null 2>&1 || BROWSER_PKG=chromium-browser
  apt-get install -y nodejs "$BROWSER_PKG" cage fonts-dejavu-core
  NODE_MAJOR=$(node -p 'process.versions.node.split(".")[0]')
  if [ "$NODE_MAJOR" -lt 18 ]; then
    echo "Node.js 18 or newer is needed (this system has $(node -v))." >&2
    exit 1
  fi
  BROWSER=$(command -v chromium || command -v chromium-browser)
  id "$RUN_USER" >/dev/null 2>&1 || useradd --system --create-home --home-dir "/home/$RUN_USER" --shell /usr/sbin/nologin "$RUN_USER"
  for g in video render input audio tty; do
    if getent group "$g" >/dev/null; then usermod -aG "$g" "$RUN_USER"; fi
  done
fi

say "Installing the Signage agent…"
mkdir -p "$APP" "$ETC" "$STATE"
TMP=$(mktemp -d)
sed -n '/^__SIGNAGE_PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d > "$TMP/agent.tar.gz"
rm -rf "$APP" && mkdir -p "$APP"
tar -xzf "$TMP/agent.tar.gz" -C "$APP"
rm -rf "$TMP"
cat > "$ETC/config.json" <<'SIGNAGE_CONFIG'
__CONFIG_JSON__
SIGNAGE_CONFIG
chmod 640 "$ETC/config.json"

if [ -n "$SKIP_SYSTEM" ]; then
  say "Files installed under ${ROOT:-/} (test mode: no services were set up)."
  echo "Run the agent with:"
  echo "  SIGNAGE_CONFIG=$ETC/config.json SIGNAGE_STATE=$STATE node $APP/agent/agent.js"
  exit 0
fi

chown -R "$RUN_USER:$RUN_USER" "$BASE" "$STATE"
chgrp "$RUN_USER" "$ETC/config.json"

say "Setting up services…"
cat > /etc/systemd/system/signage-agent.service <<EOF
[Unit]
Description=Signage agent (server connection, encrypted content cache)
After=network-online.target
Wants=network-online.target

[Service]
User=$RUN_USER
Environment=SIGNAGE_CONFIG=$ETC/config.json
Environment=SIGNAGE_STATE=$STATE
Environment=SIGNAGE_LOCAL_PORT=$PORT
ExecStart=$(command -v node) $APP/agent/agent.js
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF

cat > /etc/pam.d/signage-kiosk <<'EOF'
auth     required pam_unix.so nullok
account  required pam_unix.so
session  required pam_unix.so
session  required pam_systemd.so
EOF

cat > /etc/systemd/system/signage-kiosk.service <<EOF
[Unit]
Description=Signage screen (fullscreen player on tty1)
After=systemd-user-sessions.service plymouth-quit-wait.service signage-agent.service
Wants=signage-agent.service
Conflicts=getty@tty1.service

[Service]
User=$RUN_USER
PAMName=signage-kiosk
TTYPath=/dev/tty1
TTYReset=yes
TTYVHangup=yes
TTYVTDisallocate=yes
StandardInput=tty-fail
StandardOutput=journal
StandardError=journal
UtmpIdentifier=tty1
UtmpMode=user
ExecStartPre=$(command -v node) -e "const t=Date.now();(function w(){fetch('http://127.0.0.1:$PORT/health').then(()=>process.exit(0),()=>Date.now()-t>60000?process.exit(0):setTimeout(w,1000))})()"
ExecStart=/usr/bin/cage -d -s -- $BROWSER --kiosk --noerrdialogs --disable-infobars --no-first-run --disable-session-crashed-bubble --autoplay-policy=no-user-gesture-required --ozone-platform=wayland --password-store=basic --check-for-update-interval=31536000 --user-data-dir=/home/$RUN_USER/.config/signage-chromium http://127.0.0.1:$PORT/
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF

# A desktop session would compete for the screen: this device is a screen now.
DM=""
if systemctl is-enabled display-manager.service >/dev/null 2>&1; then
  DM=$(basename "$(readlink -f /etc/systemd/system/display-manager.service)" .service)
  systemctl disable "$DM" || true
fi
systemctl set-default multi-user.target >/dev/null

# Keep the screen on.
for f in /boot/firmware/cmdline.txt /boot/cmdline.txt; do
  if [ -f "$f" ] && ! grep -q 'consoleblank=0' "$f"; then sed -i '1 s/$/ consoleblank=0/' "$f"; break; fi
done

cat > /usr/local/sbin/signage-uninstall <<EOF
#!/usr/bin/env bash
# Removes the Signage player and gives the screen back to the normal system.
set -e
systemctl disable --now signage-kiosk.service signage-agent.service 2>/dev/null || true
rm -f /etc/systemd/system/signage-kiosk.service /etc/systemd/system/signage-agent.service /etc/pam.d/signage-kiosk
systemctl daemon-reload
systemctl enable getty@tty1.service 2>/dev/null || true
if [ -n "$DM" ]; then systemctl enable "$DM" && systemctl set-default graphical.target; fi
rm -rf "$BASE" "$ETC" "$STATE"
rm -f /usr/local/sbin/signage-uninstall
echo "Signage player removed. Reboot to return to the normal desktop or console."
EOF
chmod 755 /usr/local/sbin/signage-uninstall

systemctl daemon-reload
systemctl disable getty@tty1.service 2>/dev/null || true
systemctl enable signage-agent.service signage-kiosk.service
systemctl restart signage-agent.service
systemctl restart signage-kiosk.service || true

say "Done. The screen now shows the Signage player."
echo "If this screen has not been paired yet it shows a 6-letter code:"
echo "in the Signage console go to Screens > Pair a screen and enter it."
echo
echo "Status:  systemctl status signage-agent    Logs:  journalctl -u signage-agent -f"
echo "Remove:  sudo signage-uninstall"
echo "Rebooting is recommended so everything starts the way it will from now on."
exit 0
__SIGNAGE_PAYLOAD_BELOW__
